const allowed = [
  "billing", "technical", "delivery", "other"
];

return $input.all().map((item, index) => {
  const ticket = item.json;
  const errors = [];

  const readText = (field) =>
    typeof ticket[field] === "string"
      ? ticket[field].trim()
      : "";

  const ticket_id = readText("ticket_id");
  const customer_name = readText("customer_name");
  const message = readText("message");
  const category = readText("category").toLowerCase();

  if (!ticket_id) errors.push("Missing ticket ID");
  if (!customer_name) errors.push("Missing customer name");
  if (!message) errors.push("Missing customer message");
  if (!allowed.includes(category)) {
    errors.push("Unsupported category");
  }

  const valid = errors.length === 0;

  return {
    json: {
      ticket_id,
      customer_name,
      message,
      category,
      valid,
      validation_errors: errors,
      status: valid
        ? "ready_for_processing"
        : "needs_investigation"
    },
    pairedItem: { item: index }
  };
});
